package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

@Repository
public class PeriodRepository {

    private static final RowMapper<Period> ROW = (rs, n) -> new Period(rs.getString("sheet_id"),
            rs.getString("name"), rs.getObject("from_date", LocalDate.class).toString(),
            rs.getObject("to_date", LocalDate.class).toString(), rs.getBoolean("closed"),
            rs.getBigDecimal("closed_total") == null ? null
                    : rs.getBigDecimal("closed_total").setScale(2).toPlainString(), Map.of());

    private static final String COLUMNS = "SELECT sheet_id, name, from_date, to_date, closed, closed_total FROM period ";

    private final JdbcTemplate jdbc;

    public PeriodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, by from-date. */
    public List<Period> list(String sheetId) {
        return jdbc.query(COLUMNS + "WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId).stream()
                .map(this::withPersonTotals).toList();
    }

    /** The period with each person's due-total fixed when it was closed. */
    private Period withPersonTotals(Period p) {
        if (!p.closed()) return p;
        Map<Long, String> totals = new LinkedHashMap<>();
        jdbc.query("SELECT t.person_id, t.total FROM period_person_total t JOIN period p ON p.id = t.period_id "
                + "WHERE p.sheet_id = ? AND p.name = ? ORDER BY t.person_id",
                rs -> { totals.put(rs.getLong("person_id"), rs.getBigDecimal("total").setScale(2).toPlainString()); },
                p.sheetId(), p.name());
        return new Period(p.sheetId(), p.name(), p.from(), p.to(), true, p.closedTotal(), totals);
    }

    /** The sheet's period with the name; null when there is none. */
    public Period find(String sheetId, String name) {
        return jdbc.query(COLUMNS + "WHERE sheet_id = ? AND name = ?", ROW, sheetId, name)
                .stream().findFirst().map(this::withPersonTotals).orElse(null);
    }

    /** Refuse a change to a claim dated (yyyy-MM-dd) inside one of the sheet's closed periods. */
    public void requireOpen(String sheetId, String date) throws PeriodClosedException {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND closed "
                + "AND from_date <= ? AND to_date >= ?", Integer.class, sheetId,
                LocalDate.parse(date), LocalDate.parse(date));
        if (n != null && n > 0) {
            throw new PeriodClosedException("The claim's date is inside a closed period");
        }
    }

    /** Close the period, fixing its due-total and each person's due-total for it. */
    public Period close(Period period, BigDecimal total, Map<Long, BigDecimal> personTotals, String user) {
        for (Map.Entry<Long, BigDecimal> e : personTotals.entrySet()) {
            jdbc.update("INSERT INTO period_person_total (period_id, person_id, total) SELECT id, ?, ? "
                    + "FROM period WHERE sheet_id = ? AND name = ?",
                    e.getKey(), e.getValue(), period.sheetId(), period.name());
        }
        jdbc.update("UPDATE period SET closed = TRUE, closed_total = ?, closed_by = ?, "
                + "closed_at = CURRENT_TIMESTAMP WHERE sheet_id = ? AND name = ?",
                total, user, period.sheetId(), period.name());
        Map<Long, String> shown = new LinkedHashMap<>();
        personTotals.forEach((id, t) -> shown.put(id, t.toPlainString()));
        return new Period(period.sheetId(), period.name(), period.from(), period.to(), true,
                total.toPlainString(), shown);
    }

    /** Reopen the period: its due-total is live again. */
    public Period reopen(Period period) {
        jdbc.update("DELETE FROM period_person_total WHERE period_id IN "
                + "(SELECT id FROM period WHERE sheet_id = ? AND name = ?)", period.sheetId(), period.name());
        jdbc.update("UPDATE period SET closed = FALSE, closed_total = NULL, closed_by = NULL, "
                + "closed_at = NULL WHERE sheet_id = ? AND name = ?", period.sheetId(), period.name());
        return new Period(period.sheetId(), period.name(), period.from(), period.to(), false, null, Map.of());
    }

    /** Whether another period on the sheet has the name, compared without regard to case. */
    public boolean nameTaken(String sheetId, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND name_key = LOWER(?)",
                Integer.class, sheetId, name);
        return n != null && n > 0;
    }

    /** Whether a period on the sheet shares a day with from..to (inclusive). */
    public boolean overlaps(String sheetId, LocalDate from, LocalDate to) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? "
                + "AND from_date <= ? AND to_date >= ?", Integer.class, sheetId, to, from);
        return n != null && n > 0;
    }

    public Period add(String sheetId, String name, LocalDate from, LocalDate to, String user) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date, created_by) VALUES (?, ?, ?, ?, ?)",
                sheetId, name, from, to, user);
        return new Period(sheetId, name, from.toString(), to.toString(), false, null, Map.of());
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.DatedSetting;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Takes a statement of the person: records their due-total now (the sum of the due of their claims that
 *  count live (open ones dated within a hold of theirs, and not bound, do not), n/a ones skipped, at most the sheet's cap; n/a when their grade has no rate on the sheet's today and none of
 *  those claims keeps a settled or bound figure, or a live one at a grade no longer in force or dated on or before the sheet's today) on the sheet's today, and binds each counting claim
 *  to the figure under the due it shows now (its late charge is never bound); a claim that does not
 *  count live is unbound. */
public class TakeStatement {
    public void take(@Val Person person, PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings) {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        DatedSetting floor = settings.floor(sheetId);
        Dues.Late late = settings.late(sheetId, today);
        List<Claim> own = claims.listOf(sheetId, person.getId());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int bound = 0;
        for (Claim c : own) {
            if (!person.countsLive(c)) {
                c.bind(false, null);
            } else {
                String grade = person.gradeOn(c.getDate());
                Rate rate = rates.find(sheetId, grade, LocalDate.parse(c.getDate()));
                String live = rate == null ? null : Dues.of(c.getAmount(), rate.pct(), floor.on(c.getDate()), late.rounding(c.getRoundDate()));
                String shown = Dues.shown(c, live, late);
                kept |= c.getSettledDue() != null || c.isBound()
                        || (rate != null && (!grade.equals(person.getGrade())
                                || !LocalDate.parse(c.getDate()).isAfter(today)));
                if (shown != null) total = total.add(new BigDecimal(shown));
                // The figure under it is bound; its late charge keeps following the sheet's today.
                c.bind(true, c.due(live));
                bound++;
            }
            claims.updateBinding(c);
        }
        boolean na = rates.find(sheetId, person.getGrade(), today) == null && !kept;
        BigDecimal cap = settings.cap(sheetId);
        if (cap != null && total.compareTo(cap) > 0) total = cap.setScale(2);
        person.stated(na ? null : total.toPlainString(), today.toString(), bound);
        people.updateStatements(person);
    }
}
